// Two faint concentric rings frame every device in the classic C2 session-graph
// idiom (BloodHound/Cobalt Strike). They stay a neutral steel-grey; the LOUD
// outer ring + halo that encodes compromise is the cytoscape node border + glow
// (see viz.ts / NetworkMap), so the icon art itself never bakes in state.
const RING_FRAME =
  "<circle cx='32' cy='32' r='30.2' fill='#121212'/>" +
  "<circle cx='32' cy='32' r='30.2' fill='none' stroke='#3a3a3a' stroke-width='1.3'/>" +
  "<circle cx='32' cy='32' r='24' fill='none' stroke='#2a2a2a' stroke-width='1' opacity='.85'/>";

const STATE_COLOR: Partial<Record<CompromiseLevel, string>> = {
  user: "#d4b257",
  admin: "#db8038",
  system: "#d9554e",
  domain_admin: "#d65a8c",
};

// Compromise lives in the ART, Cobalt-Strike style: a colour wash recolours the
// device toward the compromise hue (clean stays its natural colour, owned warms
// to red, apex to magenta), stronger as severity climbs. `mix-blend-mode: color`
// keeps the device's shading while swapping its hue, so it reads as "owned" the
// way a CS beacon host does — no tacked-on badge.
const WASH_OPACITY: Partial<Record<CompromiseLevel, number>> = {
  user: 0.26,
  admin: 0.4,
  system: 0.52,
  domain_admin: 0.62,
};
const stateWash = (level: CompromiseLevel): string => {
  const c = STATE_COLOR[level];
  const op = WASH_OPACITY[level];
  if (!c || !op)
      return "";
  return `<circle cx='32' cy='32' r='22.5' fill='${c}' opacity='${op}' style='mix-blend-mode:color'/>`;
};

// Drop the puffy floating contact-shadows for a flatter, more technical read.
const deflate = (svg: string): string => svg.replace(/<ellipse[^>]*fill='#000'[^>]*\/>/g, "");

/** A full-color `data:` URI for a node icon — the device, centered and scaled to
 *  sit inside the concentric ring frame, recoloured by compromise.
 *  - `glyphKey` remaps which kind's icon is drawn (operator theming via theme.glyphs).
 *  - `variant` selects an alternate form factor for that kind (theme.variants);
 *    falls back to the kind's recommended default when omitted or unknown.
 *  - `compromise` washes the device toward its compromise hue (clean = no wash). */
export function iconDataUri(
  kind: NodeKind,
  glyphKey?: NodeKind,
  variant?: string,
  compromise: CompromiseLevel = "unknown",
): string {
  const k = glyphKey ?? kind;
  let inner = ICONS[k] ?? ICONS.custom;
  if (variant) {
    const v = ICON_VARIANTS[k]?.find((x) => x.variant === variant);
    if (v) inner = v.svg;
  }
  const framed =
    `${RING_FRAME}<g transform='translate(32 32) scale(0.72) translate(-32 -32)'>${deflate(inner)}</g>${stateWash(compromise)}`;
  const svg =
    `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'><defs>${PALETTE}</defs>${framed}</svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

/** Variant labels available for a kind (for the appearance picker). */
export const iconVariants = (k: NodeKind): string[] =>
  (ICON_VARIANTS[k] ?? []).map((v) => v.variant);
